package com.bank.backtest;

import java.math.BigDecimal;
import java.util.logging.Logger;

// Backtests single buy-then-sell profit for National Bank of India trading app.
public class BacktestService {
    private static final Logger log = Logger.getLogger(BacktestService.class.getName());

    // Max profit from one buy then one later sell. O(n), O(1). 0 if no gain.
    public BigDecimal maxSingleTradeProfit(BigDecimal[] prices) {
        if (prices == null || prices.length < 2) {
            return BigDecimal.ZERO;                 // cannot buy then sell later
        }
        BigDecimal minPrice = prices[0];            // cheapest day so far
        BigDecimal best = BigDecimal.ZERO;          // 0 = no-trade allowed
        for (int i = 1; i < prices.length; i++) {
            BigDecimal profitToday = prices[i].subtract(minPrice); // sell today
            if (profitToday.compareTo(best) > 0) {
                best = profitToday;                 // better profit found
            }
            if (prices[i].compareTo(minPrice) < 0) {
                minPrice = prices[i];               // new cheaper buy point
            }
        }
        final BigDecimal result = best;
        log.info(() -> "Best single-trade profit = Rs." + result);
        return best;
    }
}
