package com.bank.backtest;

import java.math.BigDecimal;
import java.util.logging.ConsoleHandler;
import java.util.logging.Logger;

// Runnable demo: backtest best single-trade profit for Rajesh.
public class BacktestDemo {
    private static final Logger log = Logger.getLogger(BacktestDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new BankLogFormatter());
        root.addHandler(handler);
    }

    private static BigDecimal bd(String s) { return new BigDecimal(s); }

    public static void main(String[] args) {
        BacktestService service = new BacktestService();

        // Share daily closes: buy at 180 (day 1), sell at 310 (day 4) → 130.
        BigDecimal[] rising = { bd("250"), bd("180"), bd("200"), bd("310"), bd("290") };
        BigDecimal p1 = service.maxSingleTradeProfit(rising);
        log.info(() -> "Rajesh rising-window best profit: Rs." + p1);

        // Monotonically falling: no profitable trade → 0.
        BigDecimal[] falling = { bd("400"), bd("350"), bd("300"), bd("250") };
        BigDecimal p2 = service.maxSingleTradeProfit(falling);
        log.info(() -> "Rajesh falling-window best profit: Rs." + p2);
    }
}
